Rules.InvariantScript:
With(
    {
        TABLE: "style='font-family: Segoe UI, sans-serif; border-collapse: collapse; width: 100%; margin-top: 12px; border: 1px solid #ccc; table-layout: fixed;'",
        TH1: "style='width: 120px; font-size: 12px; padding: 6px; background-color: #f0f2f5; color: #333; border: 1px solid #ccc; text-align: left;'",
        TH2: "style='width: 90px; font-size: 12px; padding: 6px; background-color: #f0f2f5; color: #333; border: 1px solid #ccc; text-align: center;'",
        TH3: "style='width: 200px; font-size: 12px; padding: 6px; background-color: #f0f2f5; color: #333; border: 1px solid #ccc; text-align: left;'",
        TH4: "style='width: 150px; font-size: 12px; padding: 6px; background-color: #f0f2f5; color: #333; border: 1px solid #ccc; text-align: left;'",
        TH5: "style='width: 100px; font-size: 12px; padding: 6px; background-color: #f0f2f5; color: #333; border: 1px solid #ccc; text-align: center;'",
        TH6: "style='width: 180px; font-size: 12px; padding: 6px; background-color: #f0f2f5; color: #333; border: 1px solid #ccc; text-align: left;'",
        TH7: "style='width: 90px; font-size: 12px; padding: 6px; background-color: #f0f2f5; color: #333; border: 1px solid #ccc; text-align: center;'",
        TH8: "style='width: 110px; font-size: 12px; padding: 6px; background-color: #f0f2f5; color: #333; border: 1px solid #ccc; text-align: center;'",
        TD: "style='border: 1px solid #ddd; padding: 6px; font-size: 12px; vertical-align: top; text-align: left; word-wrap: break-word;'",
        TDc: "style='border: 1px solid #ddd; padding: 6px; font-size: 12px; vertical-align: middle; text-align: center;'",
        LABEL: "style='font-weight: 600; color: #444; font-size: 13px;'",
        VALUE: "style='color: #000; font-size: 13px;'"
    },
    "
    <style>
        @page {
            size: A4 landscape;
            margin: 12mm;
        }
        body {
            -webkit-print-color-adjust: exact;
            font-family: 'Segoe UI', sans-serif;
            color: #000;
        }
        table {
            page-break-inside: auto;
            border-collapse: collapse;
        }
        tr {
            page-break-inside: avoid;
            page-break-after: auto;
        }
        th, td {
            word-break: break-word;
        }
    </style>
    <div style='
        font-family: Segoe UI, sans-serif;
        background-color: #ffffff;
        padding: 14px 18px;
        width: 100%;
        max-width: 1120px;
        margin: auto;
    '>
        <header style='border-bottom: 2px solid #6046ed; margin-bottom: 12px; padding-bottom: 6px;'>
            <h1 style='margin: 0; color: #6046ed; font-size: 18px;'>
                " & Upper(var_tituloModulo) & "
            </h1>
        </header>
        <p style='margin: 0 0 8px 0; line-height: 1.6;'>
            <span " & LABEL & ">Protocolo:</span>
            <span " & VALUE & ">" & var_detalhesCKREA.Protocolo & "</span><br>
            <span " & LABEL & ">Aeroporto:</span>
            <span " & VALUE & ">" & var_detalhesCKREA.Bloco & " - " & var_detalhesCKREA.IATA & " - " & var_detalhesCKREA.Aeroporto & "</span><br>
            <span " & LABEL & ">Data:</span>
            <span " & VALUE & ">" & Text(
        var_detalhesCKREA.Data,
        "[$-pt-BR]dd/mm/yyyy HH:mm"
    ) & "</span><br>" & If(
        var_tituloModulo = "Teste de DEA",
        "<span " & LABEL & ">Localização:</span> <span " & VALUE & ">" & var_detalhesCKREA.Localização & "</span><br>"
    ) & "<span " & LABEL & ">Responsável pelo preenchimento:</span>
             <span " & VALUE & ">" & var_detalhesCKREA.'Criado por'.DisplayName & "</span>
        </p>
        <table " & TABLE & ">
            <thead>
                <tr>
                    <th " & TH1 & ">ITEM</th>
                    <th " & TH2 & ">RESPOSTA</th>
                    <th " & TH3 & ">DESCRIÇÃO</th>
                    <th " & TH4 & ">AÇÃO TOMADA</th>
                    <th " & TH5 & ">Nº CHAMADO</th>
                    <th " & TH6 & ">SOLUÇÃO / TRATATIVA</th>
                    <th " & TH7 & ">STATUS</th>
                    <th " & TH8 & ">DATA SOLUÇÃO</th>
                </tr>
            </thead>
            <tbody>" & Concat(
        col_detalhesREAitens,
        "
                    <tr>
                        <td " & TD & ">" & LookUp(
            tbl_Checklist_REA_classe,
            ID = ID_item_classe,
            Item
        ) & "</td>
                        <td " & TDc & ">" & Coalesce(
            ThisRecord.Resposta,
            "-"
        ) & "</td>
                        <td " & TD & ">" & Coalesce(
            ThisRecord.Descricao,
            "-"
        ) & "</td>
                        <td " & TD & ">" & Coalesce(
            ThisRecord.'Ação Tomada',
            "-"
        ) & "</td>
                        <td " & TDc & ">" & Coalesce(
            ThisRecord.Chamado,
            "-"
        ) & "</td>
                        <td " & TD & ">" & Coalesce(
            ThisRecord.'Solução/Tratativa',
            "-"
        ) & "</td>
                        <td " & TDc & ">" & Coalesce(
            If(
                ThisRecord.Resposta = "Não conforme",
                If(
                    IsBlank(ThisRecord.'Ação Tomada') And IsBlank(ThisRecord.'Solução/Tratativa'),
                    "Em Aberto",
                    "Em Atendimento"
                ),
                If(
                    IsBlank(ThisRecord.'Ação Tomada') Or IsBlank(ThisRecord.'Solução/Tratativa'),
                    "Finalizado",
                    "Solucionado"
                )
            ),
            "-"
        ) & "</td>
                        <td " & TDc & ">" & If(
            !IsBlank(ThisRecord.'Data da Solução'),
            Text(
                ThisRecord.'Data da Solução',
                "[$-pt-BR]dd/mm/yyyy HH:mm"
            ),
            "-"
        ) & "</td>
                    </tr>"
    ) & "
            </tbody>
        </table>
        <footer style='border-top: 1px solid #ddd; margin-top: 12px; padding-top: 8px; font-size: 11px; color: #555;'>
            <em>Este relatório foi gerado automaticamente via Airport Now em " & Text(
        Now(),
        "[$-pt-BR]dd/mm/yyyy HH:mm"
    ) & ".</em>
        </footer>
    </div>"
)

